local M = class("CastingSwordShareView",LikeOO.OOPopBase)

M.m_uiName = "CastingSwordMeeting/CastingSwordShare"  -- prefab name
M.m_size_type = 2
M.m_iphoneXAdapter = true

function M:onEnter()
    EventDispatcher:registerEvent("refresh_castingSwordShareTask", {self, self.addHandler})
    self:bindUI()
    self:refreshUI()
end

-- 界面刷新
function M:addHandler(event, data)
    self.m_model:getNetData("sword_share_index", {}, function(response)
        if response then
            if self.m_control:activityOverExamine(response) then
                return
            end
            self.m_model:setAllTask(response.share_quests)
            self:refreshUI()
        end
    end, nil, nil, nil)
end

function M:bindUI()
    self:setTextByLanKey("close_title_text", "castingSword_str_0039")
    self:setTextByLanKey("text_shareText", "castingSword_str_0016")
    self:setTextByLanKey("text_hintTitle", "castingSword_str_0019")
    self:setTextByLanKey("text_title", "castingSword_str_0020")
    self:setTextByLanKey("text_hint", "castingSword_str_0017")
    self:refreshActivityTimer()
end

function M:refreshActivityTimer()
    local startTimer = self.m_model.m_activityData.start_ts
    local endTimer = self.m_model.m_activityData.end_ts
    local starT = TimeUtil.gmTime(startTimer)
    local endT = TimeUtil.gmTime(endTimer)
    local timerFormat = Language:getTextByKey("castingSword_str_0012", starT.year, starT.month, starT.day,
            endT.year, endT.month, endT.day)
    self:setTextByLanKey("text_timer", "castingSword_str_0011",timerFormat)
end

function M:refreshUI()
    self:refreshShowRedBagBtn()
    self:createLoopScroll()
    self:refreshShowRedDot()
end

function M:refreshShowRedDot()
    local openId = self.m_model.m_activityData.open_id
    local redDontId = tonumber(openId + 100000)
    local red_bl = RedPointUtil:hasRedPointById(redDontId)
    local red_point_img = self:findGameObject("redDot")
    red_point_img:SetActive(red_bl == true)
end

function M:refreshShowRedBagBtn()
    -- 官方包才有
    local isOfficialBag = false
    if SDKUtil.is_gmsdk then
        local bundleid = SDKUtil.sdk_params.applicationId or ""
        if bundleid == "com.hermes.wl" then
            -- 是官方包
            isOfficialBag = true
        end
    end
    if isOfficialBag then
        isOfficialBag = self.m_model:isOpenRedBagActivity()
    end
    self:setObjectVisible("btn_redPacketBtn",isOfficialBag)
end

function M:createLoopScroll()
    local data = self.m_model.m_allTaskData
    if self.m_scroll_view == nil then
        local loopscroll = self:findGameObject("loopscroll")
        local params ={
            show_data = data,
            loop_scroll_object = loopscroll,
            update_cell =function(index, cell_obj, cell_data)
                self:update_Gift(cell_obj, cell_data, index)
            end,
            click_func = function(index, cell_object, cell_data, click_object, click_name) -- 点击回调
                if click_name == "btn_canGotBtn" then
                    -- 领取
                    local params = {vsn = self.m_model.m_version, quest_id = cell_data.id}
                    self.m_model:getNetData("sword_recv_share_reward", params, function(response)
                        if response then
                            if self.m_control:activityOverExamine(response) then
                                return
                            end
                            RewardUtil:rewardTipsByData(response.reward)
                            cell_data.serverData.status = 2
                            self.m_model:amendTaskData(cell_data.id)
                            local luaBehaviour = UIUtil.findLuaBehaviour(cell_object)
                            self:refreshTaskBtns(luaBehaviour, cell_data.serverData.status)
                            --self:refreshUI()
                        end
                    end, nil, nil, nil)
                end
            end
        }
        self.m_scroll_view = LoopScrollViewUtil.new(params)
    else
        self.m_scroll_view:reloadData(data)
    end
end

function M:refreshTaskBtns(luaBehaviour, status)
    if luaBehaviour then
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "text_unfinished", status == 0)
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "btn_canGotBtn", status == 1)
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "text_gotBtnText", status == 2)
    end
end

function M:update_Gift(cell_obj, cell_data, index)
    local luaBehaviour = UIUtil.findLuaBehaviour(cell_obj)
    if luaBehaviour then
        local transform = cell_obj.transform
        local xlsxData = cell_data.xlsxData
        local serverData = cell_data.serverData
        local titleName = Language:getTextByKey(xlsxData.name)
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour, "text_taskTitle", titleName .. "(".. serverData.value .."/"..xlsxData.target_value..")")
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour,"text_unfinished","castingSword_str_0015")
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour,"text_gotBtnText","castingSword_str_0005")
        LuaBehaviourUtil.setTextByLanKey(luaBehaviour,"text_canGotBtnText","castingSword_str_0014")
        self:refreshTaskBtns(luaBehaviour, serverData.status)
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "line1", index == 1)
        LuaBehaviourUtil.setObjectVisible(luaBehaviour, "line2", index ~= 1)
        -- 奖励
        for i = 1, 2 do
            local awardData = xlsxData.reward or {}
            local reward_node = UIUtil.findRectTransform(transform, "awardNode"..i)
            UIUtil.destroyAllChild(reward_node)
            if awardData[i] then
                local itemNode = GameUtil:createItemElement(awardData[i], true, true)
                itemNode.transform:SetParent(reward_node.transform, false)
            end
        end
        
    end
end

function M:destroy()
    RedPointUtil:saveLocalRedPointFreshTime("CastingSwordShareBtnState")
    EventDispatcher:unRegisterEvent("refresh_castingSwordShareTask", {self, self.addHandler})
    M.super.destroy(self)
end

return M